using UnityEngine; namespace PersiaWar.Unity2D5D.UI.Loadout { public static class MenuTheme { public static void DrawBackdrop(Texture2D pixel){Color old=GUI.color;for(int i=0;i<12;i++){GUI.color=Color.Lerp(new Color(.01f,.025f,.05f,1),new Color(.04f,.17f,.27f,1),i/11f);GUI.DrawTexture(new Rect(0,i*Screen.height/12f,Screen.width,Screen.height/12f+1),pixel);}for(int i=0;i<22;i++){float x=Mathf.Repeat(i*137.31f+Mathf.Sin(Time.unscaledTime*.11f+i)*9,Screen.width);float y=Mathf.Repeat(i*83.17f+Time.unscaledTime*(3+i%3),Screen.height);GUI.color=new Color(.8f,.9f,1,.15f+(i%3)*.06f);GUI.DrawTexture(new Rect(x,y,2,2),pixel);}Matrix4x4 oldMatrix=GUI.matrix;GUI.color=new Color(.94f,.68f,.23f,.22f);float bandY=Screen.height-34f;for(int d=0;d<Mathf.CeilToInt(Screen.width/34f);d++){Rect diamond=new Rect(d*34f+10f,bandY,12f,12f);GUIUtility.RotateAroundPivot(45f,diamond.center);GUI.DrawTexture(diamond,pixel);GUI.matrix=oldMatrix;}GUI.color=old;} public static void DrawPanel(Rect r,Texture2D pixel){Color old=GUI.color;GUI.color=new Color(0,0,0,.25f);GUI.DrawTexture(new Rect(r.x+4,r.y+6,r.width,r.height),pixel);GUI.color=new Color(.018f,.042f,.075f,.97f);GUI.DrawTexture(r,pixel);GUI.color=new Color(.94f,.68f,.23f,1);GUI.DrawTexture(new Rect(r.x,r.y,r.width,3),pixel);GUI.DrawTexture(new Rect(r.x,r.y,3,r.height),pixel);GUI.color=old;} } }